
namespace UniConnect.MAUI.Models
{
    // BACKEND:
    // Represents a deadline notification displayed on the Dashboard.
    // Currently, notifications are generated by the frontend using task data.
    // This model does not currently require a separate database table.
    public class NotificationModel
    {
        // BACKEND:0
        // Unique identifier for the notification.
        // Currently, the frontend uses the associated TaskId as this value.
        public long NotificationId { get; set; }

        // BACKEND:
        // ID of the task that triggered this notification.
        // Used to identify which task the notification relates to.
        public long TaskId { get; set; }

        // BACKEND:
        // Message displayed to the user.
        // Examples:
        // "Complete project documentation is overdue."
        // "Complete project documentation is due today."
        // "Complete project documentation is due tomorrow."
        public string Message { get; set; } = string.Empty;

        // BACKEND:
        // Deadline of the task associated with this notification.
        public DateTime DueDate { get; set; }

        // BACKEND:
        // Indicates whether the notification has been read.
        // Currently defaults to false when generated by the frontend.
        // Persistent read/unread status would require backend storage.
        public bool IsRead { get; set; }

        // BACKEND:
        // Identifies the type of deadline notification.
        // Possible values:
        // OVERDUE
        // DUE_TODAY
        // DUE_TOMORROW
        public string NotificationType { get; set; } = string.Empty;
    }
}
